package kr.co.aifect.app.karaoke;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.Files;
public class VocalActivityTest{@Test public void emptyAndSungIntervalsFollowDryPcmNotBacking()throws Exception{File dry=Files.createTempFile("vocal-guide",".pcm").toFile();try{byte[] data=new byte[PcmFiles.RATE*10*2];for(int i=0;i<data.length/2;i++){double x=.002*Math.sin(i*2*Math.PI*900/PcmFiles.RATE)+.004*Math.sin(i*2*Math.PI*30/PcmFiles.RATE);if(i>=PcmFiles.RATE&&i<PcmFiles.RATE*3)x+=.12*Math.sin(i*2*Math.PI*300/PcmFiles.RATE);short sample=(short)(x*32768);data[i*2]=(byte)sample;data[i*2+1]=(byte)(sample>>8);}Files.write(dry.toPath(),data);double[][] ranges=VocalActivity.detect(dry,100,10);assertEquals(1,ranges.length);assertEquals(.82,ranges[0][0],.02);assertEquals(2.98,ranges[0][1],.02);Files.write(dry.toPath(),new byte[PcmFiles.RATE*2]);assertEquals(0,VocalActivity.detect(dry,0,1).length);}finally{dry.delete();}}}
